"""Compare the frontend snapshot with the schema generated by the real API.

Reading a committed JSON file alone cannot detect API drift. Schema
generation is in-memory: no HTTP server or database connection is needed.
"""

import json
from pathlib import Path

import pytest

from app.main import create_app

pytestmark = pytest.mark.unit


def test_frontend_openapi_snapshot_matches_current_api():
    snapshot = Path(__file__).resolve().parents[2] / "frontend/src/features/review/openapi.json"
    expected = json.loads(snapshot.read_text())
    assert create_app().openapi() == expected, "API changed: review the contract and regenerate with make sync-openapi"
